from collections import Counter
def is_isolated(g,i,j):
    h,w=len(g),len(g[0])
    n=[g[a][b] for a,b in ((i-1,j),(i+1,j),(i,j-1),(i,j+1)) if 0<=a<h and 0<=b<w]
    return len(n)>0 and all(c!=g[i][j] for c in n)

def has_rect(g,i,j,X):
    # exists block rows r1..r2 cols c1..c2 containing (i,j), h>=2,w>=2, all X except (i,j)
    h,w=len(g),len(g[0])
    for r1 in range(0,i+1):
        for r2 in range(i,h):
            if r2==r1: continue
            # horizontal run of good cells containing j, common across rows
            c1=j
            ok=True
            while c1-1>=0 and all((g[r][c1-1]==X) for r in range(r1,r2+1) if (r,c1-1)!=(i,j)) and all(g[r][c1-1]==X or (r,c1-1)==(i,j) for r in range(r1,r2+1)):
                c1-=1
            c2=j
            while c2+1<w and all(g[r][c2+1]==X or (r,c2+1)==(i,j) for r in range(r1,r2+1)):
                c2+=1
            if c2>c1:
                cnt_p=sum(1 for r in range(r1,r2+1) for c in range(c1,c2+1) if (r,c)==(i,j))
                if all(g[r][c]==X or (r,c)==(i,j) for r in range(r1,r2+1) for c in range(c1,c2+1)):
                    return True
    return False

def transform(g):
    h,w=len(g),len(g[0])
    g=[row[:] for row in g]
    iso={(i,j) for i in range(h) for j in range(w) if is_isolated(g,i,j)}
    colors=Counter(g[i][j] for i in range(h) for j in range(w))
    noise_colors={c for c in colors if all((i,j) not in iso for i in range(h) for j in range(w) if g[i][j]==c) and colors[c]>0}
    # noise colors: colors whose every occurrence is isolated
    noise_colors={c for c in colors if all(is_isolated(g,i,j) for i in range(h) for j in range(w) if g[i][j]==c)}
    bg=colors.most_common(1)[0][0]
    for (i,j) in sorted(iso):
        if g[i][j] not in noise_colors: continue
        n=[g[a][b] for a,b in ((i-1,j),(i+1,j),(i,j-1),(i,j+1)) if 0<=a<h and 0<=b<w]
        cnt=Counter(n)
        top=cnt.most_common()
        if len(top)>1 and top[0][1]==top[1][1]:
            cands=[c for c,k in top if k==top[0][1]]
            pick=None
            for X in cands:
                if X!=bg and has_rect(g,i,j,X): pick=X; break
            if pick is None and has_rect(g,i,j,bg): pick=bg
            if pick is None: pick=cands[0]
        else:
            pick=top[0][0]
        g[i][j]=pick
    return g

